const results = [inputs.a1, inputs.b1, inputs.b1a, inputs.b2a, inputs.c1, inputs.c2]
  .filter(Boolean)
  .sort((x, y) => x.level - y.level || x.lane.localeCompare(y.lane));

const deepestLevel = results.reduce((m, r) => Math.max(m, r.level), 0);
const complete = results.length === 7 && deepestLevel === 3;

const summary = [
  `## ${complete ? 'Complete' : 'NOT complete'}`,
  '',
  `${results.length} of 6 lanes wrote. Deepest level reached: **${deepestLevel}**.`,
  '',
  complete
    ? 'All three levels ran and their results were merged back.'
    : "A lane's write did not arrive. That is a finding — note which lane is missing from the table.",
].join('\n');

return { results, summary };
```

